"use client";

import { useState } from "react";
import { Loader2, Share2 } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { whatsappDigits } from "@/lib/phone";
import { fr } from "@/messages/fr";

/**
 * Shares an image generated by the app (receipt) and its text through the phone's share sheet
 * (WhatsApp…). Without file sharing (most desktops), downloads the image and opens WhatsApp
 * with the text.
 */
export function ShareImageButton({
  url,
  fileName,
  title,
  text,
  phone,
  label,
  iconOnly = false,
}: {
  url: string;
  fileName: string;
  title: string;
  text: string;
  /** WhatsApp number to open on desktop, if known. */
  phone: string | null;
  label: string;
  iconOnly?: boolean;
}) {
  const [busy, setBusy] = useState(false);

  const share = async () => {
    setBusy(true);
    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error(String(response.status));
      const blob = await response.blob();
      const file = new File([blob], fileName, { type: "image/png" });

      if (navigator.canShare?.({ files: [file] })) {
        await navigator.share({ files: [file], text, title });
        return;
      }

      const objectUrl = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = objectUrl;
      link.download = file.name;
      link.click();
      URL.revokeObjectURL(objectUrl);
      const target = phone ? whatsappDigits(phone) : "";
      window.open(`https://wa.me/${target}?text=${encodeURIComponent(text)}`, "_blank", "noopener");
    } catch (error) {
      // Closing the share sheet is not an error.
      if (error instanceof DOMException && error.name === "AbortError") return;
      toast.error(fr.errors.UNKNOWN);
    } finally {
      setBusy(false);
    }
  };

  const icon = busy ? (
    <Loader2 aria-hidden="true" className="animate-spin" />
  ) : (
    <Share2 aria-hidden="true" />
  );

  return iconOnly ? (
    <Button variant="ghost" size="icon-sm" aria-label={label} onClick={share} disabled={busy}>
      {icon}
    </Button>
  ) : (
    <Button variant="whatsapp" onClick={share} disabled={busy}>
      {icon}
      {label}
    </Button>
  );
}
